SELECT sec_code4, name, industry, current_price,
       ROUND(pbr, 2) AS pbr, ROUND(per, 1) AS per, ROUND(dividend_yield * 100, 2) AS dividend_yield_pct,
       ROUND(payout_ratio * 100, 0) AS payout_ratio_pct, market_cap_b
FROM m_screener
WHERE pbr > 0 AND pbr < {{max_pbr}}
  AND dividend_yield > {{min_yield_pct}} / 100
  AND market_cap_b >= {{min_mcap_oku}}
  AND (payout_ratio IS NULL OR payout_ratio <= {{max_payout_pct}} / 100)
ORDER BY dividend_yield DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, current_price,
       ROUND(roe * 100, 1) AS roe_pct, ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr,
       ROUND(operating_margin * 100, 1) AS operating_margin_pct, market_cap_b
FROM m_screener
WHERE roe >= {{min_roe_pct}} / 100 AND roe <= 1
  AND per > 0 AND per <= {{max_per}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY roe DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, market_cap_b,
       ROUND(net_cash_to_mcap * 100, 1) AS net_cash_to_mcap_pct, ROUND(pbr, 2) AS pbr, ROUND(per, 1) AS per,
       ROUND(equity_ratio * 100, 1) AS equity_ratio_pct, interest_bearing_debt_basis
FROM m_screener
WHERE net_cash_to_mcap >= {{min_ratio_pct}} / 100
  AND pbr > 0 AND pbr <= {{max_pbr}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY net_cash_to_mcap DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, ROUND(composite_score, 1) AS composite_score,
       ROUND(value_score, 1) AS value_score, ROUND(quality_score, 1) AS quality_score,
       ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr, ROUND(dividend_yield * 100, 2) AS dividend_yield_pct, market_cap_b
FROM m_screener
WHERE composite_score >= {{min_score}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY composite_score DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, current_price, ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr,
       ROUND(avg_turnover_20d / 100000000.0, 1) AS turnover_oku, ROUND(return_3m * 100, 1) AS return_3m_pct, market_cap_b
FROM m_screener
WHERE per > 0 AND per <= {{max_per}}
  AND pbr > 0 AND pbr <= {{max_pbr}}
  AND avg_turnover_20d >= {{min_turnover_oku}} * 100000000.0
ORDER BY avg_turnover_20d DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, market_cap_b,
       ROUND(roic * 100, 1) AS roic_pct, roic_tax_basis, ROUND(ev_ebitda, 1) AS ev_ebitda,
       ROUND(operating_margin * 100, 1) AS operating_margin_pct, ROUND(per, 1) AS per, ROUND(pbr, 2) AS pbr
FROM m_screener
WHERE roic >= {{min_roic_pct}} / 100 AND ev_ebitda > 0 AND ev_ebitda <= {{max_ev_ebitda}}
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY roic / ev_ebitda DESC
LIMIT {{limit}}

SELECT sec_code4, name, industry, market_cap_b,
       f_score, f_score_items, ROUND(interest_coverage, 1) AS interest_coverage, ROUND(current_ratio, 2) AS current_ratio,
       ROUND(accrual_ratio * 100, 1) AS accrual_pct, ROUND(goodwill_to_equity * 100, 0) AS goodwill_to_equity_pct,
       ROUND(pbr, 2) AS pbr, ROUND(per, 1) AS per
FROM m_screener
WHERE f_score >= {{min_f_score}}
  AND (interest_coverage IS NULL OR interest_coverage >= {{min_icr}})
  AND current_ratio >= {{min_current_ratio}}
  AND accrual_ratio <= 0
  AND market_cap_b >= {{min_mcap_oku}}
ORDER BY f_score DESC, pbr ASC
LIMIT {{limit}}
